import {describe, it, expect} from 'vitest';
import type {ChatSession} from '../types/session.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ToolResponse} from './tools/registry.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
  };
}

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registryReturning = (response: ToolResponse): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => response
  );
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

describe('afterModelResponse hook usage reporting', () => {
  const promptBuilder = new PromptBuilder('test system prompt');

  it('A turn driven through two tool rounds reports usage covering every provider call in that turn', async () => {
    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 5, totalTokens: 15}}],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 20, outputTokens: 8, totalTokens: 28}}],
        [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 40, outputTokens: 2, totalTokens: 42}}],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(reportedUsage).toEqual({
      inputTokens: 70, // 10 + 20 + 40
      outputTokens: 15, // 5 + 8 + 2
      totalTokens: 85, // 15 + 28 + 42
    });
  });

  it('A provider that reports no usage on some rounds does not make the total undefined or NaN: the rounds that reported are still counted', async () => {
    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 5, totalTokens: 15}}],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}], // No usage
        [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 2, totalTokens: 22}}],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(reportedUsage).toEqual({
      inputTokens: 30, // 10 + 20
      outputTokens: 7, // 5 + 2
      totalTokens: 37, // 15 + 22
    });
  });

  it('a turn where nothing reported still reports nothing', async () => {
    let reportedUsage: UsageMetadata | undefined = {inputTokens: 999, outputTokens: 999, totalTokens: 999};
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}], // No usage
        [{type: 'text', text: 'done'}, STOP_DONE], // No usage
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(reportedUsage).toBeUndefined();
  });
});
